schema_only_sql:
SELECT p.id, p.name, (p.prc - ps.sup_prc) AS gross_margin
FROM prods p
JOIN prod_sup ps ON p.id = ps.prod_id;

semantic_sql:
SELECT p.id, p.name, (p.prc - ps.sup_prc) AS gross_margin
FROM prods p
JOIN prod_sup ps ON p.id = ps.prod_id;

schema_only_sql:
SELECT COUNT(*) AS cancelled_orders_count 
FROM ords 
WHERE sts_cd = 'CANCELLED';

SELECT prod_id, AVG(cust_rtg) AS avg_satisfaction
FROM rvws
GROUP BY prod_id;

semantic_sql:
SELECT prod_id, AVG(cust_rtg) AS avg_satisfaction_score
FROM rvws
GROUP BY prod_id;

schema_only_sql:
SELECT ol.prod_id, SUM(ol.qty) AS total_units_sold
FROM ord_lines ol
GROUP BY ol.prod_id;

semantic_sql:
SELECT prod_id, SUM(qty) AS total_units_sold
FROM ord_lines
GROUP BY prod_id;

schema_only_sql:
SELECT SUM(ord_amt) AS total_revenue
FROM ords
WHERE sts_cd != 'Cancelled';

semantic_sql:
SELECT SUM(ord_amt) AS total_revenue
FROM ords
WHERE sts_cd IN ('P', 'P2', 'S');

schema_only_sql:
SELECT c2.id, c2.name 
FROM cats c1 
JOIN cats c2 ON c1.id = c2.par_id;

semantic_sql:
SELECT cust_id, COUNT(*) AS order_count
FROM ords
GROUP BY cust_id;

schema_only_sql:
SELECT cust_id, AVG(cust_rtg) AS average_rating
FROM rvws
GROUP BY cust_id;

semantic_sql:
SELECT cust_id, AVG(cust_rtg) AS average_rating
FROM rvws
GROUP BY cust_id;

schema_only_sql:
SELECT COUNT(*) AS excellent_reviews_count 
FROM rvws 
WHERE cust_rtg = 5;

SELECT AVG(ord_amt) AS average_transaction_value
FROM ords
WHERE sts_cd = 'shipped';

semantic_sql:
SELECT AVG(ord_amt) AS average_transaction_value
FROM ords
WHERE sts_cd = 'S';

SELECT SUM(prc * inv_qty) AS total_inventory_value
FROM prods
WHERE inv_qty > 0;

schema_only_sql:
SELECT p.cat_id, p.name, MAX(p.prc) AS max_price
FROM prods p
GROUP BY p.cat_id;

SELECT AVG(sup_prc) AS avg_supply_cost, sup_id
FROM prod_sup
GROUP BY sup_id;

semantic_sql:
SELECT AVG(sup_prc) AS avg_supply_cost, sup_id
FROM prod_sup
GROUP BY sup_id;

schema_only_sql:
SELECT DISTINCT cats.id, cats.name 
FROM cats 
JOIN prods ON cats.id = prods.cat_id;

semantic_sql:
SELECT DISTINCT c.id, c.name 
FROM cats c 
JOIN prods p ON c.id = p.cat_id;
